import { getInspectionsById } from "@/api/generated/requests/sdk.gen";
import { QUERY_ACTIONS } from "@/lib/api/queryKeys";
import { useQuery } from "@tanstack/react-query";
import { PREFETCH_STALE_TIME_MS } from "./shared";
import type { ResourceDefinition } from "./shared";

export interface InspectionParams {
  id: string;
}

export function inspectionQueryKey(id: string) {
  return [...QUERY_ACTIONS.INSPECTION_GET_BY_ID, id] as const;
}

/**
 * D7: NO withAuth() here, deliberately. This URL is generated by a host and sent
 * as a copy-link to a guest with no session, so the request must be anonymous —
 * withAuth() would attach `Bearer undefined`. §4 still governs: this builds the
 * same request the page builds, which is also anonymous.
 */
export async function fetchInspection(id: string) {
  const response = await getInspectionsById({
    path: { id },
    query: { detailed: true },
  });

  if (!response.data) {
    throw new Error("Inspection not found");
  }

  return response.data;
}

/**
 * `enabled` lets the caller hold the request (D8). `ReservationProofSection` reads
 * eager-and-conditional: the photos are wanted as soon as the page opens, but only
 * when the reservation actually HAS an inspection.
 *
 * It is not cosmetic. Without it a caller passing `undefined` for `id` gets
 * `isLoading: true` forever — `enabled: Boolean(undefined)` is false, so the query
 * never runs and never resolves, and a section reading `isLoading` would sit in its
 * loading branch for the life of the page. The signature mirrors `useReservation`'s.
 */
export function useInspection(id: string | undefined, enabled = true) {
  return useQuery({
    queryKey: inspectionQueryKey(id ?? ""),
    queryFn: () => {
      if (!id) throw new Error("Inspection ID is required");
      return fetchInspection(id);
    },
    enabled: Boolean(id) && enabled,
    staleTime: PREFETCH_STALE_TIME_MS,
  });
}

export const inspectionResource: ResourceDefinition = {
  action: QUERY_ACTIONS.INSPECTION_GET_BY_ID,
  key: ({ id }: InspectionParams) => inspectionQueryKey(id),
  fetch: ({ id }: InspectionParams) => fetchInspection(id),
};
